                </div>
                <div className="flex flex-wrap gap-2 mb-3">
                  {ALL_DAYS.map((day) => (
                    <button
                      key={day}
                      type="button"
                      onClick={() => toggleSlotDay(idx, day)}
                      className={`px-3 py-1.5 rounded-full text-xs font-bold border transition-colors ${
